def register_arrival(self):
    if self.booking_status != BookingStatus.confirmed:
        return False

    if self.stay_status != StayStatus.not_arrived:
        return False

    self.stay_status = StayStatus.checked_in
    return True

f87f5db8-8dae-41e6-8490-ddd20f94d29b.code:
def register_departure(self):
    if self.stay_status != StayStatus.checked_in:
        return False

    self.stay_status = StayStatus.checked_out
    return True

