def cancel(self):
    if self.booking_status == BookingStatus.canceled:
        return False

    if self.stay_status != StayStatus.not_arrived:
        return False

    self.booking_status = BookingStatus.canceled
    return True

9e29b3fa-8d76-4f81-a5a7-32d545eee4c6.code:
def calculate_price(self):
    nights = (self.check_out - self.check_in).days
    total = 0
    for reserved_room in self.reservedrooms:
        total += reserved_room.agreed_price * nights
        if reserved_room.additional_charges:
            total += reserved_room.additional_charges
    self.price = total
    return self.price

